_COMMANDS = {
    "inc": lambda v: v + 1,
    "dec": lambda v: v - 1,
    "double": lambda v: v * 2,
    "square": lambda v: v ** 2,
}


def handle(command, value):
    """Apply a named command to value; unknown commands return it unchanged."""
    op = _COMMANDS.get(command)
    return op(value) if op is not None else value

